1	// Bare-generic-vs-custom extraction coverage: measures what the CORE GENERIC
2	// extractor (generic-extractor.js) recovers ON ITS OWN for each
3	// integration-test page, relative to the reviewed-correct extraction for that page.
4	//
5	// For every dev/requirements/extractor/expected/*.json page we run GCal.extract() twice
6	// against the same cached HTML (dev/requirements/extractor/data/server-fetched/<name>.html):
7	//   - custom:   the normal pipeline — the generic base with the matching site
8	//               source's overrides merged over it. This is the reviewed-correct
9	//               extraction (dev/requirements/extractor/live.test.js pins it to
10	//               the case's `expected`).
11	//   - bare:     the SAME pipeline with GCal.sources emptied, which strips every
12	//               per-site override and leaves the bare generic base, exactly as
13	//               the gcec pack’s RULES.md describes for inspecting the generic
14	//               extractor on a supported page.
15	//
16	// The gap between the two IS the per-site sources' remaining value: a page where
17	// it closes to zero is a candidate for deleting that source outright — its host
18	// stays in supportedDomains, so the site stays fully supported.
19	//
20	// We then grade, field by field, how close the bare run's PRIMARY event
21	// (events[0] after the pipeline's own chronological sort) comes to the custom
22	// primary event, and separately track how many events each found (the bare run
23	// can't enumerate a listing page the way a dedicated source can). The result
24	// feeds two consumers: generic-coverage.test.js (the high-watermark gate) and
25	// the human-readable generic-coverage.GENERATED.md report.
26	//
27	// This file owns the comparison logic only; it reads the same generated
28	// load-order the popup injects and the harness uses, so it exercises the real,
29	// unmodified pipeline.
30	"use strict";
31	
32	const { readFileSync, readdirSync, existsSync } = require("node:fs");
33	const path = require("node:path");
34	const { JSDOM } = require("jsdom");
35	
36	const ROOT = path.join(__dirname, "../../../..");
37	const EXT = path.join(ROOT, "extension"); // the extension root; load-order entries are relative to it
38	const CASES_DIR = path.join(ROOT, "dev/requirements/extractor/expected");
39	// Resolves a case's <name>.{html,url} across data/server-fetched/ + data/user-submitted/.
40	const { dataFile } = require("../data-files");
41	
42	// The seven normalized event fields GCal.extract() returns (see
43	// event-extractors/assemble-events.js's norm()). CRITICAL is the subset the popup
44	// requires before it will surface a scraped event at all (title + location +
45	// start — see events-popup/popup.js's chooseContent / config.js).
46	const ALL_FIELDS = ["title", "start", "end", "location", "ctz", "eventLengthInMinutes", "description"];
47	const CRITICAL_FIELDS = ["title", "start", "location"];
48	
49	// Load the pipeline files once, in the generated injection order (the single
50	// source of truth the popup and harness both read).
51	const SOURCES = (() => {
52	  const files = JSON.parse(readFileSync(path.join(EXT, "event-extractors/load-order.generated.json"), "utf8"));
53	  return files.map((file) => readFileSync(path.join(EXT, file), "utf8"));
54	})();
55	
56	// Run the real pipeline against `html` loaded at `url` and return BOTH gradings
57	// from a SINGLE jsdom parse: the supported run, then the bare run with the
58	// site registry emptied so GCal.extract() takes the unsupported path. Parsing
59	// the page is the dominant cost here, and GCal.extract() is read-only on the DOM
